import{_ as i,o as n,c as r,ah as t}from"./chunks/framework.Bja9t6Wf.js";const c=JSON.parse('{"title":"Die Besetzung (Cast)","description":"","frontmatter":{},"headers":[],"relativePath":"cast.md","filePath":"cast.md"}'),a={name:"cast.md"};function s(l,e,o,h,m,u){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="die-besetzung-cast" tabindex="-1">Die Besetzung (Cast) <a class="header-anchor" href="#die-besetzung-cast" aria-label="Permalink to &quot;Die Besetzung (Cast)&quot;">​</a></h1><p>Für unsere Mockumentary konnten wir drei der intensivsten Schauspieler des deutschsprachigen Kinos (fiktiv) gewinnen. Ihre Aufgabe: Die moralischen Grauzonen der Geschichte mit Leben zu füllen.</p><h2 id="august-diehl-als-helmut-horten" tabindex="-1"><a href="https://www.imdb.com/de/name/nm0225944/" target="_blank" rel="noreferrer">August Diehl</a> als <em>Helmut Horten</em> <a class="header-anchor" href="#august-diehl-als-helmut-horten" aria-label="Permalink to &quot;[August Diehl](https://www.imdb.com/de/name/nm0225944/) als *Helmut Horten*&quot;">​</a></h2><p>August Diehl verkörpert den jungen Helmut Horten mit einer beunruhigenden Präzision.</p><ul><li><strong>Die Rolle:</strong> Ein Mann, der keine Gefühle zeigt, außer wenn er Bilanzen liest. Er sieht die Arisierung nicht als Verbrechen, sondern als logistische Herausforderung.</li><li><strong>Zitat vom Set:</strong> <em>&quot;Horten ist kein Bösewicht im klassischen Sinne. Er ist ein Vakuum, das alles Geld der Welt ansaugt.&quot;</em></li></ul><h2 id="birgit-minichmayr-als-heidi-horten" tabindex="-1"><a href="https://www.imdb.com/de/name/nm0591352/" target="_blank" rel="noreferrer">Birgit Minichmayr</a> als <em>Heidi Horten</em> <a class="header-anchor" href="#birgit-minichmayr-als-heidi-horten" aria-label="Permalink to &quot;[Birgit Minichmayr](https://www.imdb.com/de/name/nm0591352/) als *Heidi Horten*&quot;">​</a></h2><p>Mit ihrer unverwechselbaren Stimme und ihrer enormen Bühnenpräsenz ist Minichmayr die perfekte Wahl für die schillernde Heidi.</p><ul><li><strong>Die Rolle:</strong> Die Frau, die das Schweigen ihres Mannes in einen glanzvollen Pointillismus aus Kunst und Spenden verwandelt hat. Sie spielt Heidi als eine Frau, die genau weiß, wie viel der Staat kostet.</li><li><strong>Hintergrund:</strong> In ihren Szenen vermischt sich Wiener Schmäh mit eiskalter Machtpolitik.</li></ul><h2 id="oliver-masucci-als-bankier-schreck" tabindex="-1"><a href="https://www.imdb.com/name/nm0557908/" target="_blank" rel="noreferrer">Oliver Masucci</a> als <em>Bankier Schreck</em> <a class="header-anchor" href="#oliver-masucci-als-bankier-schreck" aria-label="Permalink to &quot;[Oliver Masucci](https://www.imdb.com/name/nm0557908/) als *Bankier Schreck*&quot;">​</a></h2><p>Masucci bringt die notwendige Wucht und den zynischen Humor für die Rolle des hessischen Strippenziehers mit.</p><ul><li><strong>Die Rolle:</strong> Der Mann fürs Grobe im feinen Zwirn. Er ist der emotionale Gegenpol zu Horten – laut, gierig und immer mit einem Glas Schnaps in der Hand.</li></ul><hr><h2 id="udo-samel-als-august-woginger" tabindex="-1"><a href="https://www.imdb.com/name/nm0759797/" target="_blank" rel="noreferrer">Udo Samel</a> als <em>August Wöginger</em> <a class="header-anchor" href="#udo-samel-als-august-woginger" aria-label="Permalink to &quot;[Udo Samel](https://www.imdb.com/name/nm0759797/) als *August Wöginger*&quot;">​</a></h2><p>Udo Samel verkörpert den ÖVP-Klubobmann als Meister der regionalen Intervention.</p><ul><li><strong>Die Rolle:</strong> Der „Bestimmungstäter“. Samel spielt Wöginger als einen Mann, der Macht nicht durch Gewalt, sondern durch Gefälligkeiten ausübt. In seinem Blick liegt die kühle Logik des oberösterreichischen Machterhalts.</li><li><strong>Zitat vom Set:</strong> <em>&quot;Wöginger glaubt wirklich, er tue nur das Beste für seine Heimat. Das macht die Figur so gefährlich und faszinierend zugleich.&quot;</em></li></ul><hr><p><em>Weitere Ankündigungen zum Cast folgen in Kürze.</em></p>',17)])])}const g=i(a,[["render",s]]);export{c as __pageData,g as default};
